package com.nigson.experience.consent;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
class PhoneKeysTest {
 @Test void dummyKeysAreExplicitLocalOnlyAndCannotMixWithWrappedPolicy(){byte[] first=new byte[32],second=new byte[32];Arrays.fill(first,(byte)7);Arrays.fill(second,(byte)9);String h=Base64.getEncoder().encodeToString(first),c=Base64.getEncoder().encodeToString(second);assertThat(PhoneKeys.load(null,"test",1,"synthetic","","","",h,c,"{}").hashVersion()).isEqualTo(1);for(String env:List.of("dev","qa","stage","prod"))assertThatThrownBy(()->PhoneKeys.load(null,env,1,"synthetic","","","",h,c,"{}")).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->PhoneKeys.load(null,"test",1,"synthetic","","wrapped","",h,c,"{}")).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->PhoneKeys.load(null,"test",1,"synthetic","","","","","","{}")).isInstanceOf(IllegalArgumentException.class);}
 @Test void incompleteOrAmbiguousKeyRotationFailsClosed(){String key=Base64.getEncoder().encodeToString(new byte[32]);assertThatThrownBy(()->PhoneKeys.load(null,"test",0,"synthetic","","","",key,key,"{}")).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->PhoneKeys.load(null,"test",1,"synthetic","","","",key,key,"{\"old\":\"a\",\"old\":\"b\"}")).isInstanceOf(RuntimeException.class);}
 @Test void actualKmsSdkUsesDistinctPurposeContextsAndRefusesHttpInsideTransaction()throws Exception{
  String arn="arn:aws:kms:eu-west-1:000000000000:key/00000000-0000-0000-0000-000000000001";var requests=new java.util.concurrent.CopyOnWriteArrayList<tools.jackson.databind.JsonNode>();var server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);server.createContext("/",x->{var request=com.nigson.shared.events.EventCodec.JSON.readTree(x.getRequestBody().readNBytes(4096));requests.add(request);byte[] raw=new byte[32];Arrays.fill(raw,(byte)(request.path("EncryptionContext").path("kind").asString().equals("cipher")?9:7));byte[] body=com.nigson.shared.events.EventCodec.JSON.writeValueAsBytes(Map.of("KeyId",arn,"Plaintext",Base64.getEncoder().encodeToString(raw)));x.getResponseHeaders().set("Content-Type","application/x-amz-json-1.1");x.sendResponseHeaders(200,body.length);x.getResponseBody().write(body);x.close();});server.start();
  try(var kms=software.amazon.awssdk.services.kms.KmsClient.builder().region(software.amazon.awssdk.regions.Region.EU_WEST_1).endpointOverride(java.net.URI.create("http://127.0.0.1:"+server.getAddress().getPort())).credentialsProvider(software.amazon.awssdk.auth.credentials.StaticCredentialsProvider.create(software.amazon.awssdk.auth.credentials.AwsBasicCredentials.create("mock-phone-kms","mock-phone-kms-secret"))).build()){
   var keys=PhoneKeys.load(kms,"test",1,"synthetic",arn,"AA==","AQ==","","","{}");assertThat(keys.hashVersion()).isEqualTo(1);assertThat(requests).hasSize(2);for(var request:requests){assertThat(request.path("KeyId").asString()).isEqualTo(arn);assertThat(request.path("EncryptionContext").path("purpose").asString()).isEqualTo("nigson-experience-phone");}assertThat(requests.get(0).path("EncryptionContext").path("kind").asString()).isEqualTo("lookup-proof");assertThat(requests.get(1).path("EncryptionContext").path("kind").asString()).isEqualTo("cipher");
   org.springframework.transaction.support.TransactionSynchronizationManager.setActualTransactionActive(true);try{assertThatThrownBy(()->PhoneKeys.load(kms,"test",1,"synthetic",arn,"AA==","AQ==","","","{}")).isInstanceOf(IllegalStateException.class).hasMessage("PHONE_KEY_HTTP_OUTSIDE_TRANSACTION_REQUIRED");}finally{org.springframework.transaction.support.TransactionSynchronizationManager.setActualTransactionActive(false);}assertThat(requests).hasSize(2);
  }finally{server.stop(0);}
 }
}
